export const VOICE_FPS = 30;
export const VOICE = {"en":{"learn":{"duration":15.76,"cues":[{"who":"NURI","text":"Let's solve it together. What should we do with the +3?","start":0.6,"end":3.5},{"who":"Student","text":"Move it to the other side?","start":3.95,"end":5.44},{"who":"NURI","text":"Exactly. 11 − 3 gives us 2x = 8.","start":5.79,"end":9.63},{"who":"NURI","text":"Now divide both sides by 2. So x = 4. Well done!","start":10.13,"end":14.16}],"env":""},"reception":{"duration":11.82,"cues":[{"who":"NURI","text":"Hi, welcome in! Would you like to take a number?","start":0.6,"end":3.23},{"who":"Customer","text":"Yes, please.","start":3.63,"end":4.57},{"who":"NURI","text":"You're A012. It's about five minutes.","start":4.92,"end":7.66},{"who":"NURI","text":"I've let the staff know you're here. Have a seat!","start":8.11,"end":10.22}],"env":""},"assist":{"duration":16.01,"cues":[{"who":"You","text":"NURI, what matters most today?","start":0.6,"end":2.38},{"who":"NURI","text":"Three things. Your 9:30 client call comes first.","start":2.78,"end":5.82},{"who":"NURI","text":"Then quotation #24. The draft is ready on your laptop.","start":6.12,"end":9.89},{"who":"You","text":"Great, show me.","start":10.29,"end":11.27},{"who":"NURI","text":"It's open. I won't send anything until you say so.","start":11.62,"end":14.41}],"env":""},"companion":{"duration":13.35,"cues":[{"who":"NURI","text":"Good evening, Mak Su. Have you taken your 9 pm medicine?","start":0.6,"end":4.32},{"who":"Mak Su","text":"Yes, just now.","start":4.77,"end":6.04},{"who":"NURI","text":"Great. Shall I call Aisyah to say goodnight?","start":6.39,"end":8.65},{"who":"Mak Su","text":"Yes, please.","start":9.05,"end":10.16},{"who":"NURI","text":"Calling Aisyah now…","start":10.51,"end":11.75}],"env":""}},"ms":{"learn":{"duration":18.94,"cues":[{"who":"NURI","text":"Okey, jom kita selesaikan sama-sama. Tambah 3 ni, kita nak alih ke mana?","start":0.6,"end":4.82},{"who":"Pelajar","text":"Hmm, pindah ke sebelah sana ke?","start":5.27,"end":7.65},{"who":"NURI","text":"Betul! 11 − 3, jadi 2x = 8.","start":8.0,"end":12.24},{"who":"NURI","text":"Sekarang bahagi 2 kedua-dua belah. Jadi x = 4. Pandai!","start":12.74,"end":17.34}],"env":""},"reception":{"duration":15.76,"cues":[{"who":"NURI","text":"Hai, selamat datang! Nak ambil nombor giliran?","start":0.6,"end":3.88},{"who":"Pelanggan","text":"Boleh, boleh. Terima kasih.","start":4.28,"end":6.06},{"who":"NURI","text":"Nombor anda A012. Tunggu lebih kurang lima minit ya.","start":6.41,"end":10.83},{"who":"NURI","text":"Saya dah bagitahu staf. Jemput duduk dulu!","start":11.28,"end":14.16}],"env":""},"assist":{"duration":22.3,"cues":[{"who":"Anda","text":"NURI, hari ni apa yang paling penting?","start":0.6,"end":3.26},{"who":"NURI","text":"Ada tiga. Yang paling utama, call dengan klien pukul 9:30.","start":3.66,"end":8.49},{"who":"NURI","text":"Lepas tu, sebut harga #24. Draf dah siap dalam laptop.","start":8.79,"end":14.4},{"who":"Anda","text":"Okey, tunjuk kat saya.","start":14.8,"end":16.25},{"who":"NURI","text":"Dah buka. Saya tak hantar apa-apa selagi awak tak setuju.","start":16.6,"end":20.7}],"env":""},"companion":{"duration":16.93,"cues":[{"who":"NURI","text":"Selamat malam, Mak Su. Ubat pukul 9 tadi dah makan?","start":0.6,"end":4.67},{"who":"Mak Su","text":"Dah, baru tadi.","start":5.12,"end":6.39},{"who":"NURI","text":"Bagus. Nak saya telefon Aisyah, ucap selamat malam?","start":6.74,"end":10.23},{"who":"Mak Su","text":"Boleh juga. Terima kasih, NURI.","start":10.63,"end":12.86},{"who":"NURI","text":"Okey, saya telefon Aisyah sekarang…","start":13.21,"end":15.33}],"env":""}}};
